DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261104104218_Phase3') THEN
    CREATE TABLE "Hr_PayComponentTypes" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "Name" character varying(100) NOT NULL,
        "Kind" character varying(20) NOT NULL,
        "Method" character varying(20) NOT NULL,
        "Rate" numeric(18,4) NOT NULL,
        "IsStatutory" boolean NOT NULL,
        "IsActive" boolean NOT NULL,
        "DefaultForAll" boolean NOT NULL,
        "CreatedOn" timestamp with time zone NOT NULL,
        CONSTRAINT "PK_Hr_PayComponentTypes" PRIMARY KEY ("Id")
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261104104218_Phase3') THEN
    CREATE TABLE "Hr_PayrollRuns" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "Year" integer NOT NULL,
        "Month" integer NOT NULL,
        "Status" character varying(20) NOT NULL,
        "GeneratedOn" timestamp with time zone NOT NULL,
        "GeneratedBy" character varying(200),
        "ApprovedOn" timestamp with time zone,
        "ApprovedBy" character varying(200),
        "PaidOn" timestamp with time zone,
        "PaidBy" character varying(200),
        "TotalGross" numeric(18,2) NOT NULL,
        "TotalDeductions" numeric(18,2) NOT NULL,
        "TotalStatutory" numeric(18,2) NOT NULL,
        "TotalNet" numeric(18,2) NOT NULL,
        "JournalEntryId" integer,
        "PaymentJournalEntryId" integer,
        "Notes" character varying(1000),
        "BranchId" integer,
        CONSTRAINT "PK_Hr_PayrollRuns" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_Hr_PayrollRuns_journal_entries_JournalEntryId" FOREIGN KEY ("JournalEntryId") REFERENCES journal_entries (id) ON DELETE SET NULL,
        CONSTRAINT "FK_Hr_PayrollRuns_journal_entries_PaymentJournalEntryId" FOREIGN KEY ("PaymentJournalEntryId") REFERENCES journal_entries (id) ON DELETE SET NULL
    );
    END IF;
END $EF$;

